insert into public.listening_items (slug, part, prompt, transcript, options, correct_key, difficulty, category, track_id, status, source) values ('l2-01', 2, 'When does the new accountant start working here?', 'When does the new accountant start working here? A. On the second floor. B. Next Monday, I think. C. She has ten years of experience.', '[{"key":"A","text":"On the second floor."},{"key":"B","text":"Next Monday, I think."},{"key":"C","text":"She has ten years of experience."}]'::jsonb, 'B', 2, 'listening-wh', null, 'published', 'json') on conflict (slug) do nothing;
insert into public.listening_items (slug, part, prompt, transcript, options, correct_key, difficulty, category, track_id, status, source) values ('l2-02', 2, 'Where should I put these shipping boxes?', 'Where should I put these shipping boxes? A. I''d like to order two of them. B. They shipped them yesterday. C. Just leave them by the loading dock.', '[{"key":"A","text":"I''d like to order two of them."},{"key":"B","text":"They shipped them yesterday."},{"key":"C","text":"Just leave them by the loading dock."}]'::jsonb, 'C', 2, 'listening-wh', null, 'published', 'json') on conflict (slug) do nothing;
insert into public.listening_items (slug, part, prompt, transcript, options, correct_key, difficulty, category, track_id, status, source) values ('l2-03', 2, 'Who is organizing the staff retreat this year?', 'Who is organizing the staff retreat this year? A. Ms. Alvarez from Human Resources. B. In late September, I believe. C. It''s at a lakeside resort.', '[{"key":"A","text":"Ms. Alvarez from Human Resources."},{"key":"B","text":"In late September, I believe."},{"key":"C","text":"It''s at a lakeside resort."}]'::jsonb, 'A', 2, 'listening-wh', null, 'published', 'json') on conflict (slug) do nothing;
insert into public.listening_items (slug, part, prompt, transcript, options, correct_key, difficulty, category, track_id, status, source) values ('l2-04', 2, 'Why was the client meeting postponed?', 'Why was the client meeting postponed? A. At two o''clock in the afternoon. B. The presenter is stuck at the airport. C. I''ve already sent the invitation.', '[{"key":"A","text":"At two o''clock in the afternoon."},{"key":"B","text":"The presenter is stuck at the airport."},{"key":"C","text":"I''ve already sent the invitation."}]'::jsonb, 'B', 2, 'listening-wh', null, 'published', 'json') on conflict (slug) do nothing;
insert into public.listening_items (slug, part, prompt, transcript, options, correct_key, difficulty, category, track_id, status, source) values ('l2-05', 2, 'How can I reserve a conference room?', 'How can I reserve a conference room? A. Use the online booking system. B. It holds about twenty people. C. Yes, the projector works well.', '[{"key":"A","text":"Use the online booking system."},{"key":"B","text":"It holds about twenty people."},{"key":"C","text":"Yes, the projector works well."}]'::jsonb, 'A', 2, 'listening-wh', null, 'published', 'json') on conflict (slug) do nothing;
insert into public.listening_items (slug, part, prompt, transcript, options, correct_key, difficulty, category, track_id, status, source) values ('l2-06', 2, 'Have you finished the sales presentation yet?', 'Have you finished the sales presentation yet? A. Almost, I only need to add the charts. B. No, the presentation room is full. C. She presented it last year.', '[{"key":"A","text":"Almost, I only need to add the charts."},{"key":"B","text":"No, the presentation room is full."},{"key":"C","text":"She presented it last year."}]'::jsonb, 'A', 2, 'listening-yes-no', null, 'published', 'json') on conflict (slug) do nothing;
insert into public.listening_items (slug, part, prompt, transcript, options, correct_key, difficulty, category, track_id, status, source) values ('l2-07', 2, 'Is the printer on the third floor working?', 'Is the printer on the third floor working? A. I''ll print three copies. B. Yes, the third quarter was strong. C. The technician fixed it this morning.', '[{"key":"A","text":"I''ll print three copies."},{"key":"B","text":"Yes, the third quarter was strong."},{"key":"C","text":"The technician fixed it this morning."}]'::jsonb, 'C', 2, 'listening-yes-no', null, 'published', 'json') on conflict (slug) do nothing;
insert into public.listening_items (slug, part, prompt, transcript, options, correct_key, difficulty, category, track_id, status, source) values ('l2-08', 2, 'Would you like to meet on Tuesday or Wednesday?', 'Would you like to meet on Tuesday or Wednesday? A. Wednesday works better for me. B. Yes, I would like some tea. C. At the downtown office.', '[{"key":"A","text":"Wednesday works better for me."},{"key":"B","text":"Yes, I would like some tea."},{"key":"C","text":"At the downtown office."}]'::jsonb, 'A', 2, 'listening-choice', null, 'published', 'json') on conflict (slug) do nothing;
insert into public.listening_items (slug, part, prompt, transcript, options, correct_key, difficulty, category, track_id, status, source) values ('l2-09', 2, 'Should we send the contract by e-mail or by courier?', 'Should we send the contract by e-mail or by courier? A. The contract is thirty pages long. B. It needs an original signature, so by courier. C. No, I don''t have the e-mail address.', '[{"key":"A","text":"The contract is thirty pages long."},{"key":"B","text":"It needs an original signature, so by courier."},{"key":"C","text":"No, I don''t have the e-mail address."}]'::jsonb, 'B', 2, 'listening-choice', null, 'published', 'json') on conflict (slug) do nothing;
insert into public.listening_items (slug, part, prompt, transcript, options, correct_key, difficulty, category, track_id, status, source) values ('l2-10', 2, 'Could you help me carry these files to the archive room?', 'Could you help me carry these files to the archive room? A. The files are in alphabetical order. B. Yes, he carries a briefcase. C. Sure, I''ll take half of them.', '[{"key":"A","text":"The files are in alphabetical order."},{"key":"B","text":"Yes, he carries a briefcase."},{"key":"C","text":"Sure, I''ll take half of them."}]'::jsonb, 'C', 2, 'listening-request', null, 'published', 'json') on conflict (slug) do nothing;
insert into public.listening_items (slug, part, prompt, transcript, options, correct_key, difficulty, category, track_id, status, source) values ('l2-11', 2, 'Why don''t we order lunch for the training session?', 'Why don''t we order lunch for the training session? A. The training starts at nine. B. Good idea. I''ll check the menu options. C. He ordered it last week.', '[{"key":"A","text":"The training starts at nine."},{"key":"B","text":"Good idea. I''ll check the menu options."},{"key":"C","text":"He ordered it last week."}]'::jsonb, 'B', 2, 'listening-request', null, 'published', 'json') on conflict (slug) do nothing;
insert into public.listening_items (slug, part, prompt, transcript, options, correct_key, difficulty, category, track_id, status, source) values ('l2-12', 2, 'I think the projector in Room B needs a new bulb.', 'I think the projector in Room B needs a new bulb. A. Room B is on the left. B. The meeting starts in an hour. C. I''ll tell maintenance right away.', '[{"key":"A","text":"Room B is on the left."},{"key":"B","text":"The meeting starts in an hour."},{"key":"C","text":"I''ll tell maintenance right away."}]'::jsonb, 'C', 2, 'listening-statement', null, 'published', 'json') on conflict (slug) do nothing;
